html:
{% macro _money(val, curr) %}{% if frappe is defined and frappe.utils is defined and frappe.utils.fmt_money is defined %}{{ frappe.utils.fmt_money(val or 0, currency=curr) | e }}{% elif curr %}{{ val }} {{ curr | e }}{% else %}{{ val }}{% endif %}{% endmacro %}
{% set _copy_no = doc.get("copy_number") or (frappe.db.get_value("URY Bill Reprint Log", {"invoice": doc.name}, "copy_number", order_by="copy_number desc") if (frappe is defined and frappe.db is defined and doc.get("name")) else none) or 1 %}
{% set partner = doc.get("ury_print_partner") %}
{% set bills = [doc, partner] if partner else [doc] %}
<article>
<h1>{{ _("COPY") }} #{{ _copy_no }}</h1>
<p>{{ _("Original invoice") }}: {{ doc.name | e }}<br>{{ _("Reprinted") }}: {{ doc.copy_timestamp or frappe.utils.now() }}<br>{{ _("Posting date") }}: {{ doc.posting_date }}</p>
{% for bill in bills %}
{% if bill is not sameas doc %}<h2>{{ _("Merged invoice") }}: {{ bill.name | e }}</h2>{% endif %}
<table class="table table-condensed"><thead><tr><th>{{ _("Item") }}</th><th>{{ _("Qty") }}</th><th>{{ _("Amount") }} ({{ bill.currency | e }})</th></tr></thead><tbody>
{% for row in bill.get('items') %}<tr><td>{{ row.item_name | e }}</td><td>{{ row.qty }}</td><td>{{ _money(row.amount, bill.currency) }}</td></tr>{% endfor %}</tbody></table>
{% for tax in bill.taxes %}<p>{{ tax.description | striptags | e }}: {{ _money(tax.tax_amount, bill.currency) }}</p>{% endfor %}
<p>{{ _("Grand total") }}: {{ _money(bill.grand_total, bill.currency) }}<br>{{ _("Rounded total") }}: {{ _money(bill.rounded_total, bill.currency) }}</p>
{% for payment in bill.payments if payment.amount %}<p>{{ payment.mode_of_payment | e }}: {{ _money(payment.amount, bill.currency) }}</p>{% endfor %}
<p>{{ _("Outstanding") }}: {{ _money(bill.outstanding_amount, bill.currency) }}</p>{% if bill.outstanding_amount and bill.outstanding_amount > 0 %}<p>{{ _("Charged to account") }} {{ bill.customer | e }}: {{ _money(bill.outstanding_amount, bill.currency) }}</p>{% endif %}
{% set bill_ef = efris_receipt_data(bill) if (efris_receipt_data is defined and bill.docstatus == 1) else none %}
{% if bill_ef %}
<div class="efris" style="margin-top: 10px;">
{% if bill_ef.state == "fiscalised" %}
<p class="text-center"><b>URA EFRIS</b></p>
<p>{{ _("FDN") }} : <b>{{ bill_ef.fdn | e }}</b>{% if bill_ef.verification_code %}<br>{{ _("Verification code") }} : <b>{{ bill_ef.verification_code | e }}</b>{% endif %}{% if bill_ef.device_no %}<br>{{ _("Device No") }} : {{ bill_ef.device_no | e }}{% endif %}{% if bill_ef.issued %}<br>{{ _("Issued") }} : {{ bill_ef.issued | e }}{% endif %}{% if bill_ef.is_return and bill_ef.original_fdn %}<br>{{ _("Original FDN") }} : {{ bill_ef.original_fdn | e }}{% endif %}{% if bill.tax_id %}<br>{{ _("Buyer TIN") }} : {{ bill.tax_id | e }}{% endif %}</p>
{% set einv = frappe.get_doc("E Invoice", bill.efris_e_invoice) if bill.efris_e_invoice else none %}
{% if einv and einv.taxes %}<table class="table table-condensed"><thead><tr><th>{{ _("Tax category") }}</th><th class="text-right">{{ _("Net") }}</th><th class="text-right">{{ _("Tax") }}</th></tr></thead><tbody>{% for t in einv.taxes %}<tr><td>{{ ((t.tax_category_code or "").split(":", 1) | last) | e }}</td><td class="text-right">{{ _money(t.net_amount, bill.currency) }}</td><td class="text-right">{{ _money(t.tax_amount, bill.currency) }}</td></tr>{% endfor %}</tbody></table>{% endif %}
{% if bill_ef.qr %}<p class="text-center"><img src="{{ bill_ef.qr | e }}" alt="EFRIS QR" style="width: 34mm; height: 34mm;"></p>{% endif %}
{% elif bill_ef.state == "credit_note_pending" or (bill.is_return and bill_ef.state == "pending") %}
<p class="text-center"><b>{{ _("CREDIT NOTE PENDING URA APPROVAL") }}</b>{% if bill_ef.application_ref %}<br>{{ _("Application Ref") }} : {{ bill_ef.application_ref | e }}{% endif %}</p>
{% elif bill_ef.state == "pending" %}
<p class="text-center"><b>{{ _("FISCAL RECEIPT PENDING") }}</b><br>{{ _("Not a tax invoice until URA issues the FDN. Ask for a reprint.") }}</p>
{% else %}
<p class="text-center">{{ _("Not a fiscal receipt") }}</p>
{% endif %}
{% if bill_ef.sandbox %}<p class="text-center"><b>*** {{ _("EFRIS SANDBOX - NOT A VALID TAX INVOICE") }} ***</b></p>{% endif %}
</div>
{% endif %}
{% endfor %}
{% if partner %}<p><b>{{ _("Combined grand total") }}: {{ _money((doc.grand_total or 0) + (partner.grand_total or 0), doc.currency) }}</b></p>{% endif %}
</article>
